package io.github.alighaziam.eom.shipping.application;
import io.github.alighaziam.eom.outbox.OutboxOperations; import io.github.alighaziam.eom.shipping.*; import io.github.alighaziam.eom.shipping.infrastructure.*; import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Sort;import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.List; import java.util.UUID;
@Service public class ShippingService implements ShippingOperations {
 private final ShipmentRepository repository;private final OutboxOperations outbox;public ShippingService(ShipmentRepository r,OutboxOperations o){repository=r;outbox=o;}
 @Transactional public Shipment create(UUID orderId,DeliveryAddress a){validate(orderId,a);var old=repository.findByOrderId(orderId);if(old.isPresent())return old.get().toDomain();Instant now=Instant.now();UUID id=UUID.randomUUID();var e=repository.save(new ShipmentEntity(id,orderId,a,now));outbox.append("ShipmentCreated","Shipment",id.toString(),1,orderId.toString(),null,"{\"shipmentId\":\""+id+"\"}");return e.toDomain();}
 @Transactional public Shipment updateStatus(UUID id,ShipmentStatus next){var e=repository.findById(id).orElseThrow(()->new ShipmentNotFoundException(id));var current=e.toDomain().status();if(current==next)return e.toDomain();boolean ok=switch(current){case PENDING->next==ShipmentStatus.LABEL_CREATED||next==ShipmentStatus.CANCELLED;case LABEL_CREATED->next==ShipmentStatus.READY_FOR_DISPATCH||next==ShipmentStatus.CANCELLED;case READY_FOR_DISPATCH->next==ShipmentStatus.DISPATCHED||next==ShipmentStatus.CANCELLED;case DISPATCHED->next==ShipmentStatus.IN_TRANSIT||next==ShipmentStatus.DELIVERY_FAILED;case IN_TRANSIT->next==ShipmentStatus.DELIVERED||next==ShipmentStatus.DELIVERY_FAILED;case DELIVERY_FAILED->next==ShipmentStatus.RETURNED;case DELIVERED,RETURNED,CANCELLED->false;};if(!ok)throw new IllegalStateException("Invalid shipment transition: "+current+" -> "+next);e.status(next,Instant.now());outbox.append("Shipment"+next.name(),"Shipment",id.toString(),e.toDomain().updatedAt().toEpochMilli(),e.toDomain().orderId().toString(),null,"{\"shipmentId\":\""+id+"\",\"status\":\""+next+"\"}");return e.toDomain();}
 @Transactional(readOnly=true) public Shipment get(UUID id){return repository.findById(id).orElseThrow(()->new ShipmentNotFoundException(id)).toDomain();}
 @Transactional(readOnly=true) public List<Shipment> list(){return repository.findTop40ByOrderByCreatedAtDesc().stream().map(ShipmentEntity::toDomain).toList();}
 @Transactional(readOnly=true) public Page<Shipment> search(String q, String status, int page, int size){
  ShipmentStatus parsed=status==null||status.isBlank()?null:ShipmentStatus.valueOf(status);
  return repository.search(q==null||q.isBlank()?null:q.trim(), parsed, PageRequest.of(Math.max(page,0), Math.min(Math.max(size,1),100), Sort.by(Sort.Direction.DESC,"createdAt"))).map(ShipmentEntity::toDomain);
 }
 private void validate(UUID id,DeliveryAddress a){if(id==null||a==null||blank(a.recipientName())||blank(a.addressLine1())||blank(a.city())||a.countryCode()==null||!a.countryCode().matches("[A-Z]{2}"))throw new IllegalArgumentException("Order and complete delivery address with ISO country code are required.");}
 private boolean blank(String s){return s==null||s.isBlank();}
}